function toBase36(c)
  c = tonumber(c) or 0
  if c == 0 then
    return "0"
  end
  local d = "0123456789abcdefghijklmnopqrstuvwxyz"
  local f = ""
  while c > 0 do
    local g = c % 36
    f = d:sub(g + 1, g + 1) .. f
    c = math.floor(c / 36)
  end
  return f
end
function fromBase36(c)
  if not c or c == "" then
    return "0"
  end
  local d = "0123456789abcdefghijklmnopqrstuvwxyz"
  local f = 0
  for a = 1, #c, 1 do
    local b = c:sub(a, a)
    local g = d:find(b) or 1
    f = f * 36 + ((g - 1))
  end
  return tostring(f)
end
