      elseif d == "[/]" then
        return "<font color=\"#FFDC00\">[/]</font>" .. c:sub(4)
      elseif d == "[-]" then
        return "<font color=\"#FF5F73\">[-]</font>" .. c:sub(4)
      else
        return c
      end
    end
